package com.example.takura.communications.infrastructure;
import com.example.takura.communications.application.SnsSignatureVerifier;import com.fasterxml.jackson.databind.JsonNode;import java.io.ByteArrayInputStream;import java.net.URI;import java.net.http.*;import java.security.Signature;import java.security.cert.*;import java.time.Duration;import java.util.Base64;import org.springframework.stereotype.Component;
@Component public final class AwsSnsSignatureVerifier implements SnsSignatureVerifier{public boolean verify(JsonNode n){try{URI uri=URI.create(n.path("SigningCertURL").asText());String h=uri.getHost();if(!"https".equals(uri.getScheme())||h==null||!(h.equals("sns.amazonaws.com")||h.matches("sns\\.[a-z0-9-]+\\.amazonaws\\.com"))||!uri.getPath().matches("/SimpleNotificationService-[A-Za-z0-9]+\\.pem"))return false;byte[] bytes=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).connectTimeout(Duration.ofSeconds(3)).build().send(HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(5)).GET().build(),HttpResponse.BodyHandlers.ofByteArray()).body();if(bytes.length>65536)return false;X509Certificate cert=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(bytes));Signature sig=Signature.getInstance("2".equals(n.path("SignatureVersion").asText())?"SHA256withRSA":"SHA1withRSA");sig.initVerify(cert.getPublicKey());sig.update(canonical(n).getBytes(java.nio.charset.StandardCharsets.UTF_8));return sig.verify(Base64.getDecoder().decode(n.path("Signature").asText()));}catch(Exception e){return false;}}private static String canonical(JsonNode n){String[] f="Notification".equals(n.path("Type").asText())?new String[]{"Message","MessageId","Subject","Timestamp","TopicArn","Type"}:new String[]{"Message","MessageId","SubscribeURL","Timestamp","Token","TopicArn","Type"};StringBuilder b=new StringBuilder();for(String k:f)if(n.has(k))b.append(k).append('\n').append(n.path(k).asText()).append('\n');return b.toString();}}
